function toast(t){$("#toast").textContent=t;$("#toast").classList.add("show");clearTimeout(timer);timer=setTimeout(()=>$("#toast").classList.remove("show"),2600)}
function show(id){$$('.screen').forEach(x=>x.classList.toggle('hidden',x.id!==id));scrollTo(0,0)}
function escapeHtml(v){return String(v||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function validPaper(f){return f&&/\.(pdf|docx)$/i.test(f.name)&&f.size<=30*1024*1024}
function paperType(f){return /\.pdf$/i.test(f.name)?"PDF":"DOCX"}
function wordCount(t){const zh=(t.match(/[\u3400-\u9fff]/g)||[]).length,en=(t.match(/[A-Za-z]+(?:[-'][A-Za-z]+)*/g)||[]).length;return zh+en}
function blockType(text,index=0){const t=text.trim();if(/^(abstract|摘要|摘\s*要|keywords?|关键词|index terms?)\b[:：]?$/i.test(t))return"heading";if(/^(abstract|摘要|摘\s*要|keywords?|关键词|index terms?)\b[:：]/i.test(t))return"labelled";if(/^(\d+(?:\.\d+)*|[IVXLC]+|[A-Z])\.?\s+[\p{L}\p{N}]/u.test(t)||(/^[A-Z\d\s,:&()\-–—]+$/.test(t)&&t.length<100))return"heading";return index===0&&t.length<180?"title":"paragraph"}
function naturalBlocks(t){const raw=t.replace(/\r/g,"").split(/\n+/).map(x=>x.replace(/\s+/g," ").trim()).filter(x=>x&&/[\p{L}\p{N}]/u.test(x)),out=[];let buffer=[];const flush=()=>{if(!buffer.length)return;const text=buffer.join(" ").trim();if(text.length>2)out.push({type:blockType(text,out.length),text});buffer=[]};for(const line of raw){const type=blockType(line,out.length);if(type==="heading"||type==="labelled"||type==="title"){flush();if(type==="labelled"){const m=line.match(/^((?:abstract|摘要|摘\s*要|keywords?|关键词|index terms?)\b[:：]?)(.*)$/i);out.push({type:"heading",text:m[1].replace(/[:：]$/,'')});if(m[2].trim())out.push({type:"paragraph",text:m[2].trim()})}else out.push({type,text:line});continue}buffer.push(line);if(/[.!?。！？][\]”’')]*$/.test(line))flush()}flush();return out}
function splitText(t){return naturalBlocks(t).filter(x=>x.type!=="heading"&&x.type!=="title").map(x=>x.text)}
