function db(){return new Promise((ok,no)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE,{keyPath:"id"});if(!r.result.objectStoreNames.contains(ARCHIVE_STORE))r.result.createObjectStore(ARCHIVE_STORE,{keyPath:"id"})};r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
async function storePut(v){const d=await db();return new Promise((ok,no)=>{const t=d.transaction(STORE,"readwrite");t.objectStore(STORE).put(v);t.oncomplete=()=>ok(v);t.onerror=()=>no(t.error)})}
async function storeAll(){const d=await db();return new Promise((ok,no)=>{const r=d.transaction(STORE).objectStore(STORE).getAll();r.onsuccess=()=>ok(r.result.sort((a,b)=>b.createdAt-a.createdAt));r.onerror=()=>no(r.error)})}
async function storeDelete(id){const d=await db();return new Promise((ok,no)=>{const t=d.transaction(STORE,"readwrite");t.objectStore(STORE).delete(id);t.oncomplete=ok;t.onerror=()=>no(t.error)})}
async function archivePut(v){const d=await db();return new Promise((ok,no)=>{const t=d.transaction(ARCHIVE_STORE,"readwrite");t.objectStore(ARCHIVE_STORE).put(v);t.oncomplete=()=>ok(v);t.onerror=()=>no(t.error)})}
async function archiveAll(){const d=await db();return new Promise((ok,no)=>{const r=d.transaction(ARCHIVE_STORE).objectStore(ARCHIVE_STORE).getAll();r.onsuccess=()=>ok(r.result.sort((a,b)=>b.createdAt-a.createdAt));r.onerror=()=>no(r.error)})}
async function archiveDelete(id){const d=await db();return new Promise((ok,no)=>{const t=d.transaction(ARCHIVE_STORE,"readwrite");t.objectStore(ARCHIVE_STORE).delete(id);t.oncomplete=ok;t.onerror=()=>no(t.error)})}

async function parsePdf(file){if(!window.pdfjsLib)throw Error("PDF 解析组件加载失败，请刷新页面");pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise,pageTexts=[];for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),content=await page.getTextContent(),lines=new Map();for(const item of content.items){const y=Math.round(item.transform[5]),x=Math.round(item.transform[4]),key=[...lines.keys()].find(k=>Math.abs(k-y)<=3)??y;if(!lines.has(key))lines.set(key,[]);lines.get(key).push({x,text:item.str})}const ordered=[...lines.entries()].sort((a,b)=>b[0]-a[0]).map(([,items])=>items.sort((a,b)=>a.x-b.x).map(i=>i.text).join(' ').trim()).filter(Boolean);pageTexts.push(ordered.join('\n'))}return{text:pageTexts.map((t,i)=>`${t}\n\n〔第 ${i+1} 页〕`).join('\n\n'),pages:pdf.numPages,pageTexts}}
async function parseDocx(file){if(!window.mammoth)throw Error("Word 解析组件加载失败，请刷新页面");const r=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return{text:r.value,pages:null}}
async function parseFile(file,batchId="single"){if(!validPaper(file))throw Error(file?.size>30*1024*1024?"文件超过 30 MB":"请选择 PDF 或 DOCX 文件（旧版 DOC 暂不支持）");const parsed=paperType(file)==="PDF"?await parsePdf(file):await parseDocx(file),pageBlocks=(parsed.pageTexts||[parsed.text]).map(naturalBlocks),paragraphs=pageBlocks.flat().filter(x=>x.type==="paragraph").map(x=>x.text);if(!paragraphs.length)throw Error("没有提取到正文；扫描版 PDF 请先进行 OCR");const paper={id:crypto.randomUUID(),name:file.name,type:paperType(file),size:file.size,createdAt:Date.now(),batchId,pages:parsed.pages,words:wordCount(parsed.text),text:parsed.text,paragraphs,chunks:chunksOf(paragraphs),pageBlocks,pageParagraphs:pageBlocks.map(x=>x.map(b=>b.text)),translationPages:{},translation:[],notes:[],drawings:{},fileBlob:file};await storePut(paper);return paper}

