function bindDrop(zone,input,cb){zone.onclick=()=>input.click();['dragover','dragenter'].forEach(n=>zone.addEventListener(n,e=>{e.preventDefault();zone.style.background="#edf5fc"}));zone.ondragleave=()=>zone.style.background="";zone.ondrop=e=>{e.preventDefault();zone.style.background="";cb(e.dataTransfer.files[0])};input.onchange=e=>cb(e.target.files[0])}
