function selectParagraph(el){currentParagraph=Number(el.dataset.p);$$('.annotatable').forEach(y=>y.classList.toggle('focus',y===el));const selected=window.getSelection()?.toString().trim();if(selected)el.dataset.quote=selected;toast(selected?'已选择文字，可点击“批注当前段落”':'已选择当前段落')}
function bindInk(){const ink=$("#inkCanvas");$("#penToggle").onclick=()=>{penEnabled=!penEnabled;$("#penToggle").classList.toggle('active',penEnabled);ink.style.pointerEvents=penEnabled?'auto':'none';toast(penEnabled?'画笔已开启，可直接在论文上勾画':'画笔已关闭')};const point=e=>{const r=ink.getBoundingClientRect();return{x:(e.clientX-r.left)*ink.width/r.width,y:(e.clientY-r.top)*ink.height/r.height}};ink.onpointerdown=e=>{if(!penEnabled)return;drawing=true;ink.setPointerCapture(e.pointerId);const p=point(e),c=ink.getContext('2d');c.beginPath();c.moveTo(p.x,p.y)};ink.onpointermove=e=>{if(!drawing)return;const p=point(e),c=ink.getContext('2d');c.lineCap='round';c.lineJoin='round';c.strokeStyle=$("#penColor").value;c.lineWidth=Number($("#penSize").value)*devicePixelRatio;c.lineTo(p.x,p.y);c.stroke()};ink.onpointerup=async()=>{drawing=false;currentPaper.drawings=currentPaper.drawings||{};currentPaper.drawings[currentPdfPage]=ink.toDataURL();await storePut(currentPaper)};$("#clearInk").onclick=async()=>{ink.getContext('2d').clearRect(0,0,ink.width,ink.height);delete currentPaper.drawings?.[currentPdfPage];await storePut(currentPaper);toast('已清除本页勾画')}}

function changePdfPage(delta){if(!currentPaper?.pages)return;currentPdfPage=Math.max(1,Math.min(currentPaper.pages,currentPdfPage+delta));syncPdfPage()}
async function syncPdfPage(){const label=$("#pdfPageLabel");if(label)label.textContent=`第 ${currentPdfPage} / ${currentPaper.pages} 页`;if($("#pdfPrev"))$("#pdfPrev").disabled=currentPdfPage===1;if($("#pdfNext"))$("#pdfNext").disabled=currentPdfPage===currentPaper.pages;if(activePdfDoc&&$("#pdfCanvas")){const page=await activePdfDoc.getPage(currentPdfPage),base=page.getViewport({scale:1}),host=$("#pdfCanvas").parentElement,scale=Math.min(2.2,Math.max(1.1,(host.clientWidth||650)/base.width)),v=page.getViewport({scale}),canvas=$("#pdfCanvas"),ink=$("#inkCanvas");canvas.width=ink.width=Math.floor(v.width*devicePixelRatio);canvas.height=ink.height=Math.floor(v.height*devicePixelRatio);canvas.style.aspectRatio=ink.style.aspectRatio=`${v.width}/${v.height}`;await page.render({canvasContext:canvas.getContext('2d'),viewport:page.getViewport({scale:scale*devicePixelRatio})}).promise;const saved=currentPaper.drawings?.[currentPdfPage];if(saved){const im=new Image();im.onload=()=>ink.getContext('2d').drawImage(im,0,0,ink.width,ink.height);im.src=saved}}renderTranslationPage()}
function renderTranslationPage(){const col=$$("#singleReading .parallel article")[1];if(!col||!currentPaper)return;const blocks=currentPaper.pageBlocks?.[currentPdfPage-1]||(currentPaper.pageParagraphs?.[currentPdfPage-1]||currentPaper.paragraphs||[]).map((text,i)=>({type:blockType(text,i),text})),translations=currentPaper.translationPages?.[currentPdfPage]||[],ready=translations.some(Boolean),body=ready?blocks.map((b,i)=>{const t=typeof translations[i]==='string'?translations[i]:translations[i]?.text||'';return b.type==='heading'||b.type==='title'?`<h3 class="paper-heading">${escapeHtml(t)}</h3>`:`<p class="annotatable translated-paragraph" data-p="${i}">${escapeHtml(t)}</p>`}).join(''):`<div class="paper-wait"><b>第 ${currentPdfPage} 页等待翻译</b><small>系统先识别标题、摘要与自然段，再逐段翻译；不合并、不拆分、不显示序号。</small></div>`;col.innerHTML=`<span>TRANSLATED PAPER · 第 ${currentPdfPage} 页</span><div class="translation-head"><h3>自然段对照译文</h3><button id="translatePage" class="outline">${ready?'重新翻译本页':'翻译本页'}</button></div><div class="translated-paper-page">${body}</div>`;$("#translatePage").onclick=translateCurrent;col.querySelectorAll('.annotatable').forEach(x=>x.onclick=()=>selectParagraph(x))}

async function renderPdfPages(blob){const host=$("#pdfPages");if(!host||!blob)return;try{const pdf=await pdfjsLib.getDocument({data:await blob.arrayBuffer()}).promise;host.innerHTML='';for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),base=page.getViewport({scale:1}),target=Math.max(560,host.clientWidth-20),scale=Math.min(2,target/base.width),view=page.getViewport({scale}),wrap=document.createElement('section'),canvas=document.createElement('canvas'),label=document.createElement('small');wrap.className='pdf-page';label.textContent=`第 ${n} / ${pdf.numPages} 页`;canvas.width=Math.floor(view.width);canvas.height=Math.floor(view.height);canvas.style.width='100%';canvas.style.height='auto';wrap.append(label,canvas);host.append(wrap);await page.render({canvasContext:canvas.getContext('2d',{alpha:false}),viewport:view}).promise}}catch(e){host.innerHTML=`<div class="empty-card"><b>PDF 页面显示失败</b><p>${escapeHtml(e.message)}</p></div>`}}

