const bd=$("#batchDrop"),bf=$("#batchFiles");bd.onclick=()=>bf.click();['dragover','dragenter'].forEach(n=>bd.addEventListener(n,e=>{e.preventDefault();bd.style.background="#edf5fc"}));bd.ondragleave=()=>bd.style.background="";bd.ondrop=e=>{e.preventDefault();bd.style.background="";useBatch([...e.dataTransfer.files])};bf.onchange=e=>useBatch([...e.target.files]);
async function useBatch(files){const good=files.filter(validPaper);if(!good.length)return toast("请选择不超过 30 MB 的 PDF 或 DOCX 文献");const batchId=`batch-${Date.now()}`;for(const f of good){const row=document.createElement('div');row.innerHTML=`<span>${paperType(f)}</span><b>${escapeHtml(f.name)}</b><em>解析中…</em>`;$("#batchList").prepend(row);try{await parseFile(f,batchId);row.querySelector('em').textContent="本次导入 · 解析完成"}catch(e){row.querySelector('em').textContent="失败："+e.message}}localStorage.setItem('rf-last-batch',batchId);await refreshLibrary();toast(`本次批量导入已建立：${good.length} 篇文献`)}

