function batchLabel(id,papers){if(id==='single'||!id)return'单篇导入';const first=papers.find(p=>p.batchId===id);return first?new Date(first.createdAt).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'历史批次'}
function getFolders(){return JSON.parse(localStorage.getItem('rf-folders')||'[]')}
function saveFolders(v){localStorage.setItem('rf-folders',JSON.stringify(v))}
async function refreshLibraryV2(){const papers=await storeAll(),last=localStorage.getItem('rf-last-batch'),list=$("#batchList");if(list){const groups=papers.reduce((a,p)=>((a[p.batchId||'single']??=[]).push(p),a),{});list.innerHTML=papers.length?Object.entries(groups).map(([id,ps])=>`<section class="batch-group ${id===last?'current-batch':''}"><header><b>${id===last?'本次批量导入':batchLabel(id,papers)}</b><em>${ps.length} 篇 · ${new Date(ps[0].createdAt).toLocaleString()}</em></header>${ps.map(p=>`<div data-paper="${p.id}"><span>${p.type}</span><b>${escapeHtml(p.name)}</b><em>${p.paragraphs.length} 个自然段</em><button class="row-delete" data-delete-paper="${p.id}">删除</button></div>`).join('')}</section>`).join(''):'<div><b>尚未导入文献</b><em>请拖入 PDF 或 DOCX</em></div>'}const cards=$$("#overviewPanel .overview-grid article span");if(cards[0])cards[0].textContent=papers.length;if(cards[1])cards[1].textContent=papers.reduce((n,p)=>n+p.chunks.length,0);const progress=$$("#progressPanel .progress-grid article strong");if(progress[1])progress[1].textContent=`${papers.length} 篇`;if(progress[2])progress[2].textContent=`${papers.reduce((n,p)=>n+(p.notes||[]).length,0)} 条`;renderLibrary(papers);renderExistingPicker(papers);renderAnalysisPickers(papers);$$("[data-paper] button.open-paper").forEach(b=>b.onclick=()=>{currentPaper=papers.find(p=>p.id===b.closest('[data-paper]').dataset.paper);renderPaper(currentPaper);panel('single')});$$('[data-delete-paper]').forEach(b=>b.onclick=async e=>{e.stopPropagation();const p=papers.find(x=>x.id===b.dataset.deletePaper);if(!confirm(`确定删除“${p?.name||'这篇论文'}”吗？相关翻译和批注也会删除。`))return;await storeDelete(b.dataset.deletePaper);if(currentPaper?.id===b.dataset.deletePaper)resetCenterImport();await refreshLibrary();toast('论文已删除')})}
function renderLibrary(papers){const host=$("#libraryPanel .library-grid");if(!host)return;const folders=getFolders(),sort=$("#librarySort")?.value||'date';let ordered=[...papers];if(sort==='type')ordered.sort((a,b)=>a.type.localeCompare(b.type));if(sort==='folder'){const ids=folders.flatMap(f=>f.paperIds);ordered.sort((a,b)=>ids.indexOf(a.id)-ids.indexOf(b.id))}host.innerHTML=ordered.length?ordered.map(p=>`<article data-paper="${p.id}"><label><input type="checkbox" class="folder-paper" value="${p.id}"> 选择</label><b>${escapeHtml(p.name)}</b><p>${p.type} · ${new Date(p.createdAt).toLocaleString()} · ${batchLabel(p.batchId,papers)}</p><div class="paper-actions"><button class="outline open-paper">打开阅读</button><button class="delete-paper" data-delete-paper="${p.id}">删除</button></div></article>`).join(''):'<b>文献库为空</b><p>请先导入论文。</p>';$("#folderBar").innerHTML=folders.length?folders.map(f=>`<button class="folder-chip" data-folder="${f.id}">▣ ${escapeHtml(f.name)} <small>${f.paperIds.length} 篇</small></button>`).join(''):'<span>尚未创建主题文件夹</span>';$$("[data-folder]").forEach(b=>b.onclick=()=>{const f=folders.find(x=>x.id===b.dataset.folder);$$('.folder-paper').forEach(x=>x.checked=f.paperIds.includes(x.value));toast(`已选择“${f.name}”中的 ${f.paperIds.length} 篇论文`)})}
function renderExistingPicker(papers){const host=$("#existingPicker");if(!host)return;host.innerHTML=papers.length?papers.map(p=>`<label><input type="checkbox" value="${p.id}"><span>${escapeHtml(p.name)}</span><small>${new Date(p.createdAt).toLocaleString()}</small></label>`).join('')+`<button id="useExisting" class="primary">将所选论文设为本次研究</button>`:'<p>文献库中还没有论文</p>';const use=$("#useExisting");if(use)use.onclick=async()=>{const ids=$$('#existingPicker input:checked').map(x=>x.value);if(!ids.length)return toast('请先选择论文');const batchId=`batch-${Date.now()}`;for(const p of papers.filter(x=>ids.includes(x.id))){p.batchId=batchId;p.createdAt=Date.now();await storePut(p)}localStorage.setItem('rf-last-batch',batchId);host.classList.add('hidden');await refreshLibrary();toast(`已将 ${ids.length} 篇已有论文设为本次研究`)}}
function renderAnalysisPickers(papers){const cards=papers.map(p=>`<label><input type="checkbox" value="${p.id}"><span>${escapeHtml(p.name)}</span><small>${batchLabel(p.batchId,papers)}</small></label>`).join('')||'<p>请先导入论文</p>';const pick=$("#comparePicker");if(pick)pick.innerHTML=cards;const mapPick=$("#mapPaperPicker");if(mapPick)mapPick.innerHTML=cards;const single=$("#mapSingle");if(single)single.innerHTML=papers.map(p=>`<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('');const batches=[...new Set(papers.map(p=>p.batchId||'single'))],sel=$("#mapBatch");if(sel)sel.innerHTML=batches.map(id=>`<option value="${id}" ${id===localStorage.getItem('rf-last-batch')?'selected':''}>${id===localStorage.getItem('rf-last-batch')?'本次批量导入':batchLabel(id,papers)}（${papers.filter(p=>(p.batchId||'single')===id).length} 篇）</option>`).join('')}
$("#librarySort").onchange=()=>refreshLibrary();$("#newFolder").onclick=async()=>{const name=prompt('请输入主题文件夹名称');if(!name?.trim())return;const ids=$$('.folder-paper:checked').map(x=>x.value);if(!ids.length)return toast('请先勾选要放入文件夹的论文');const folders=getFolders();folders.push({id:crypto.randomUUID(),name:name.trim(),paperIds:ids,createdAt:Date.now()});saveFolders(folders);await refreshLibrary();toast('主题文件夹已创建')};
async function retrieve(q,scope){const papers=scope==='single'&&currentPaper?[currentPaper]:await storeAll(),ts=terms(q),rank=[];for(const p of papers)for(const c of p.chunks){let score=0;for(const t of ts)if(c.text.toLowerCase().includes(t))score+=t.length;rank.push({score,p,c})}return rank.sort((a,b)=>b.score-a.score).slice(0,8).map(x=>`【${x.p.name} · 段落${x.c.start+1}-${x.c.end}】\n${x.c.text}`).join('\n\n')}
function setQaMode(n){const single=n==='single'||n==='notes';$("#qaEyebrow").textContent=single?'ASK THE PAPER':'ASK ALL PAPERS';$("#qaTitle").textContent=single?'单篇论文问答':'跨文献问答';$("#qaScope").textContent=single?'当前论文':'全部文献';$("#question").placeholder=single?'向当前论文提问…':'向全部文献提问…';$("#qaWelcome").innerHTML=single?'<b>研脉 AI</b><p>问题会先检索当前论文，再依据原文片段回答。</p><small>回答附论文名与段落号</small>':'<b>研脉 AI</b><p>我会检索整个本地文献库，比较不同论文中的证据。</p><small>适合查找观点来源、分歧和研究空白</small>';$("#prompts").innerHTML=single?'<button>提取核心内容</button><button>创新点在第几段？</button><button>解释实验数据</button>':'<button>这个观点出现在哪几篇论文？</button><button>不同研究有哪些分歧？</button><button>总结共同研究空白</button>';bindPrompts()}
function bindPrompts(){$$('#prompts button').forEach(b=>b.onclick=()=>{$('#question').value=b.textContent;send()})}

async function callAI(message,context,mode='qa'){const r=await fetch('/api/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message,context,mode,scope:$("#qaScope").textContent==='当前论文'?'single':'all',apiKey:modelConfig.mode==='custom'?modelConfig.apiKey:'',model:modelConfig.model})}),data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data}
async function send(){const q=$("#question").value.trim();if(!q)return;const scope=$("#qaScope").textContent==='当前论文'?'single':'all';if(scope==='single'&&!currentPaper)return toast('请先导入并打开一篇论文');const context=await retrieve(q,scope);if(!context)return toast('文献库中没有可检索的正文');const m=$("#messages"),u=document.createElement('div'),a=document.createElement('div');u.className='message user';u.textContent=q;m.append(u);$("#question").value='';a.className='message ai';a.innerHTML='<b>研脉 AI</b><p>正在检索原文证据并生成回答…</p>';m.append(a);a.scrollIntoView({behavior:'smooth'});try{const d=await callAI(q,context);a.innerHTML=`<b>研脉 AI</b><p>${escapeHtml(d.answer).replace(/\n/g,'<br>')}</p><small>已检索真实论文正文 · ${escapeHtml(d.model||'DeepSeek')}</small>`}catch(e){a.innerHTML=`<b>研脉 AI</b><p>${escapeHtml(e.message)}</p><small>请检查模型设置或平台密钥</small>`}}
$("#send").onclick=send;$("#question").onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};bindPrompts();

async function translateCurrent(){if(!currentPaper)return;const blocks=currentPaper.pageBlocks?.[currentPdfPage-1]||(currentPaper.pageParagraphs?.[currentPdfPage-1]||currentPaper.paragraphs||[]).map((text,i)=>({type:blockType(text,i),text})),col=$$("#singleReading .parallel article")[1];if(!blocks.length)return toast('当前页没有提取到可翻译文字');col.innerHTML=`<span>译文 · 第 ${currentPdfPage} 页</span><h3>正在识别标题、摘要与自然段并逐段翻译…</h3>`;try{const tagged=blocks.map((b,i)=>`[B${i+1}|${b.type}] ${b.text}`).join('\n\n'),instruction='请先理解论文结构，再逐块翻译。每个 [B编号|类型] 对应原文的一个完整自然段或独立标题。严格保留每个标记且顺序不变，不得合并、拆分、总结或遗漏。Abstract/摘要、章节标题等必须作为独立标题块；标题译文单独一行，正文从下一行开始。',d=await callAI(instruction,tagged,'translate'),matches=[...d.answer.matchAll(/\[B(\d+)\|([a-z]+)\]\s*([\s\S]*?)(?=\n?\[B\d+\|[a-z]+\]|$)/gi)],parts=[];matches.forEach(m=>parts[Number(m[1])-1]={type:m[2],text:m[3].trim()});currentPaper.translationPages=currentPaper.translationPages||{};currentPaper.translationPages[currentPdfPage]=blocks.map((b,i)=>parts[i]||{type:b.type,text:'该自然段未返回译文'});await storePut(currentPaper);renderTranslationPage();toast(`本页 ${blocks.length} 个结构块已逐段对齐翻译`)}catch(e){col.innerHTML=`<span>翻译失败</span><h3>${escapeHtml(e.message)}</h3><p>请检查 API 设置后重试。</p>`}}

