$("#runMap").onclick=async()=>{const id=$("#mapBatch").value,papers=(await storeAll()).filter(p=>(p.batchId||'single')===id),host=$("#mapPanel .mindmap");if(!papers.length)return toast('该批次没有论文');host.innerHTML='<div class="empty-card"><b>正在构建批次研究脉络…</b></div>';const context=papers.map(p=>`【${p.name}】\n${p.paragraphs.slice(0,6).join('\n')}`).join('\n\n');try{const d=await callAI('分析这批论文的共同主题、方法分支、主要结论、相互分歧与研究空白，输出五个短标题及简洁说明。',context,'analysis'),angles=papers.map((_,i)=>i*2*Math.PI/papers.length);host.innerHTML=`<svg class="map-lines" viewBox="0 0 1000 560" preserveAspectRatio="none">${angles.map(a=>`<line x1="500" y1="280" x2="${500+330*Math.cos(a)}" y2="${280+200*Math.sin(a)}"/>`).join('')}</svg><div class="map-center"><b>本次导入</b><small>${papers.length} 篇论文</small></div>${papers.map((p,i)=>`<button class="map-paper" style="left:${50+33*Math.cos(angles[i])}%;top:${50+35*Math.sin(angles[i])}%">${escapeHtml(p.name.replace(/\.[^.]+$/,''))}</button>`).join('')}<aside class="map-summary"><b>总体研究脉络</b><p>${escapeHtml(d.answer).replace(/\n/g,'<br>')}</p></aside>`}catch(e){host.innerHTML=`<div class="empty-card"><b>生成失败</b><p>${escapeHtml(e.message)}</p></div>`}};

