function parseAIJson(text){try{return JSON.parse(text.replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim())}catch{return null}}
function radarPoints(values,r=82,c=100){return values.map((v,i)=>{const a=-Math.PI/2+i*Math.PI*2/values.length,d=r*(Number(v)||0)/5;return`${(c+d*Math.cos(a)).toFixed(1)},${(c+d*Math.sin(a)).toFixed(1)}`}).join(' ')}
$("#runCompare").onclick=async()=>{
 const ids=$$('#comparePicker input:checked').map(x=>x.value);
 const papers=(await storeAll()).filter(p=>ids.includes(p.id));
 const host=$("#comparePanel .compare-table");
 if(papers.length<2)return toast('请至少选择两篇论文');
 if(papers.length>6)return toast('一次最多选择六篇论文');
 const format=$("#compareFormat").value;
 const context=papers.map(p=>`【${p.name}】\n${p.paragraphs.slice(0,18).join('\n')}`).join('\n\n');
 host.innerHTML='<div class="empty-card"><b>正在提取研究背景、方法、数据与局限…</b></div>';
 try{
  const prompt='只依据所选论文输出纯JSON，不要Markdown。格式：{"papers":[{"name":"必须与输入论文名一致","background":"研究背景","question":"研究问题","method":"研究方法","data":"实验或数据集信息；没有则写未明确说明","conclusion":"核心结论","innovation":"创新点","limitation":"研究局限","scores":{"method":1到5,"data":1到5,"evidence":1到5,"innovation":1到5,"reproducibility":1到5,"limitation":1到5}}]}。文字项控制在80字以内；scores评价的是论文对该维度的信息完整度与证据清晰度，不是单纯按字数计算；不得编造实验结论。';
  const d=await callAI(prompt,context,'analysis');
  const j=parseAIJson(d.answer);
  const rows=['background','question','method','data','conclusion','innovation','limitation'];
  const labels={background:'研究背景',question:'研究问题',method:'研究方法',data:'实验数据',conclusion:'核心结论',innovation:'创新点',limitation:'研究局限'};
  if(!j?.papers)throw Error('结构化结果解析失败，请重试');
  const found=name=>j.papers.find(x=>x.name===name)||j.papers.find(x=>name.includes(x.name)||x.name.includes(name))||{};
  if(format==='chart'){
   const axes=[['method','方法明确度'],['data','数据完整度'],['evidence','证据清晰度'],['innovation','创新明确度'],['reproducibility','可复现性'],['limitation','局限透明度']];
   host.innerHTML=`<div class="radar-grid">${papers.map(p=>{const x=found(p.name),vals=axes.map(([k])=>Math.max(0,Math.min(5,Number(x.scores?.[k])||0))),poly=radarPoints(vals,82,100);return `<article><h3>${escapeHtml(p.name)}</h3><svg viewBox="0 0 200 200" role="img" aria-label="${escapeHtml(p.name)} 六维证据雷达图"><polygon class="radar-bg" points="${radarPoints([5,5,5,5,5,5],82,100)}"/>${[1,2,3,4].map(n=>`<polygon class="radar-ring" points="${radarPoints([n,n,n,n,n,n],82,100)}"/>`).join('')}<polygon class="radar-value" points="${poly}"/>${axes.map((a,i)=>{const ang=-Math.PI/2+i*Math.PI*2/6,xp=100+96*Math.cos(ang),yp=100+96*Math.sin(ang);return `<text x="${xp}" y="${yp}" text-anchor="middle">${a[1]}</text>`}).join('')}</svg><div class="radar-scores">${axes.map((a,i)=>`<span>${a[1]} <b>${vals[i]}/5</b></span>`).join('')}</div></article>`}).join('')}<p class="chart-note">评分表示论文在相应维度上的信息完整度和证据清晰度，不代表论文绝对质量。</p></div>`;
  }else{
   host.innerHTML=`<div class="comparison-matrix"><table><thead><tr><th>比较维度</th>${papers.map(p=>`<th>${escapeHtml(p.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(k=>`<tr><th>${labels[k]}</th>${papers.map(p=>`<td>${escapeHtml(found(p.name)[k]||'原文未明确说明')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }
  await saveAnalysisArchive('compare','对比分析',papers,host.innerHTML,{format});
  toast('所选论文对比已生成并保存');
 }catch(e){host.innerHTML=`<div class="empty-card"><b>生成失败</b><p>${escapeHtml(e.message)}</p></div>`}
};

$("#runMap").onclick=async()=>{const id=$("#mapBatch").value,papers=(await storeAll()).filter(p=>(p.batchId||'single')===id),host=$("#mapPanel .mindmap");if(!papers.length)return toast('该批次没有论文');host.innerHTML='<div class="empty-card"><b>正在提取真实研究信息并建立分支…</b></div>';const context=papers.map(p=>`【${p.name}】\n${p.paragraphs.slice(0,18).join('\n')}`).join('\n\n');try{const prompt='只依据这些论文输出纯JSON，不要Markdown。格式：{"theme":"共同研究主题，20字内","branches":[{"title":"研究背景","detail":"背景归纳并注明论文简称"},{"title":"研究问题","detail":"主要问题与差异"},{"title":"研究方法","detail":"具体模型、算法或实验方法"},{"title":"实验数据","detail":"数据集、样本、指标或实验设置；未说明则如实写"},{"title":"核心结论","detail":"共同结论与差异"},{"title":"研究局限","detail":"论文明确局限及可推断空白"}]}。每个detail不超过120字，不得编造。',d=await callAI(prompt,context,'analysis'),j=parseAIJson(d.answer);if(!j?.branches?.length)throw Error('研究地图结构解析失败，请重试');const pos=[[50,13],[79,28],[79,67],[50,84],[21,67],[21,28]],branches=j.branches.slice(0,6);host.innerHTML=`<svg class="map-lines" viewBox="0 0 1000 600" preserveAspectRatio="none">${branches.map((_,i)=>`<line x1="500" y1="300" x2="${pos[i][0]*10}" y2="${pos[i][1]*6}"/>`).join('')}</svg><div class="map-center"><b>${escapeHtml(j.theme||'本次研究主题')}</b><small>${papers.length} 篇论文</small></div>${branches.map((b,i)=>`<button class="map-branch" style="left:${pos[i][0]}%;top:${pos[i][1]}%"><b>${escapeHtml(b.title)}</b><span>${escapeHtml(b.detail)}</span></button>`).join('')}`;toast('真实研究信息思维导图已生成')}catch(e){host.innerHTML=`<div class="empty-card"><b>生成失败</b><p>${escapeHtml(e.message)}</p></div>`}};
