function archiveTarget(type){return type==='compare'?$("#comparePanel .compare-table"):type==='map'?$("#mapPanel .mindmap"):$("#reviewPanel .empty-card")}
function bindArchivedMap(host,map){if(!map?.branches)return;host.querySelectorAll('[data-map-detail]').forEach(btn=>btn.onclick=()=>{const b=map.branches[Number(btn.dataset.mapDetail)],box=host.querySelector('.map-detail');if(!b||!box)return;box.innerHTML=`<b>${escapeHtml(b.title)}</b><p>${escapeHtml(b.detail)}</p><div class="map-evidence">${(b.subtopics||[]).map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div><small>代表论文：${escapeHtml((b.evidence||[]).join('、')||'原文未明确标注')}</small>`;host.querySelectorAll('[data-map-detail]').forEach(x=>x.classList.toggle('active',x===btn))})}
async function saveAnalysisArchive(type,label,papers,html,data={}){await archivePut({id:crypto.randomUUID(),type,label,createdAt:Date.now(),paperNames:papers.map(p=>p.name),html,data});await renderArchiveBars()}
async function renderArchiveBars(){const all=await archiveAll();for(const [type,label] of [['compare','对比分析'],['map','研究地图'],['review','文献综述']]){const host=archiveTarget(type);if(!host)continue;let bar=$(`#${type}ArchiveBar`);if(!bar){bar=document.createElement('section');bar.id=`${type}ArchiveBar`;bar.className='archive-bar';host.before(bar)}const items=all.filter(x=>x.type===type);bar.innerHTML=`<div><b>${label}存档</b><small>${items.length?`已保存 ${items.length} 条历史结果`:'生成结果后自动保存，不会被新分析覆盖'}</small></div><select aria-label="选择${label}存档"><option value="">${items.length?'请选择历史记录':'暂无存档'}</option>${items.map(x=>`<option value="${x.id}">${new Date(x.createdAt).toLocaleString()} · ${escapeHtml(x.paperNames.slice(0,2).join('、'))}${x.paperNames.length>2?` 等${x.paperNames.length}篇`:''}</option>`).join('')}</select><button class="outline archive-open" ${items.length?'':'disabled'}>打开存档</button><button class="archive-delete" ${items.length?'':'disabled'}>删除</button>`;const select=bar.querySelector('select');bar.querySelector('.archive-open').onclick=()=>{const item=items.find(x=>x.id===select.value);if(!item)return toast('请先选择一条存档');host.innerHTML=item.html;if(type==='map')bindArchivedMap(host,item.data?.map);toast(`已打开历史${label}`)};bar.querySelector('.archive-delete').onclick=async()=>{const item=items.find(x=>x.id===select.value);if(!item)return toast('请先选择要删除的存档');if(!confirm(`确定删除这条${label}存档吗？`))return;await archiveDelete(item.id);await renderArchiveBars();toast('存档已删除')}}}
renderArchiveBars().catch(()=>toast('存档区域加载失败，请刷新页面'));

